"""Add MITRE profile fields to TTPs, seed threat actors, malware, and relationships from STIX.

Revision ID: 020_mitre_profiles_rels
Revises: 019_seed_mitre_attack
Create Date: 2026-03-09
"""

import base64
import json
import uuid

import sqlalchemy as sa
from sqlalchemy.dialects.postgresql import ARRAY, JSONB

from alembic import op

revision = "020_mitre_profiles_rels"
down_revision = "019_seed_mitre_attack"
branch_labels = None
depends_on = None

# MITRE ATT&CK STIX data: technique profiles, groups, malware, relationships
# Source: https://github.com/mitre-attack/attack-stix-data
# fmt: off
_MITRE_B64 = ""
# fmt: on


def _load() -> dict:
    return json.loads(base64.b64decode(_MITRE_B64))


def upgrade() -> None:
    # 1. Add MITRE profile columns to ttps
    op.add_column("ttps", sa.Column("platforms", JSONB, server_default="[]", nullable=False))
    op.add_column("ttps", sa.Column("data_sources", JSONB, server_default="[]", nullable=False))
    op.add_column("ttps", sa.Column("mitre_url", sa.Text, nullable=True))
    op.add_column("ttps", sa.Column("detection", sa.Text, nullable=True))
    op.add_column("ttps", sa.Column("is_subtechnique", sa.Boolean, server_default="false", nullable=False))

    # 2. Make created_by nullable on entity_relationships (for system-seeded relationships)
    op.alter_column("entity_relationships", "created_by", existing_type=sa.dialects.postgresql.UUID(), nullable=True)

    conn = op.get_bind()
    data = _load()

    # 3. Update TTPs with MITRE profile data
    ttps = sa.table(
        "ttps",
        sa.column("technique_id", sa.String),
        sa.column("platforms", JSONB),
        sa.column("data_sources", JSONB),
        sa.column("mitre_url", sa.Text),
        sa.column("detection", sa.Text),
        sa.column("is_subtechnique", sa.Boolean),
    )
    for tid, extra in data["techniques_extra"].items():
        conn.execute(
            ttps.update()
            .where(ttps.c.technique_id == tid)
            .values(
                platforms=extra["platforms"],
                data_sources=extra["data_sources"],
                mitre_url=extra["mitre_url"],
                detection=extra["detection"],
                is_subtechnique=extra["is_subtechnique"],
            )
        )

    # 4. Seed threat actors from MITRE
    actors_table = sa.table(
        "threat_actors",
        sa.column("id", sa.dialects.postgresql.UUID),
        sa.column("name", sa.String),
        sa.column("aliases", ARRAY(sa.Text)),
        sa.column("description", sa.Text),
        sa.column("mitre_id", sa.String),
        sa.column("article_count", sa.Integer),
        sa.column("metadata_", JSONB),
    )
    existing_actors = {
        row[0]: row[1] for row in conn.execute(sa.select(actors_table.c.name, actors_table.c.id)).fetchall()
    }
    actor_name_to_id = {}
    for group in data["groups"]:
        name = group["name"]
        if name in existing_actors:
            actor_name_to_id[name] = existing_actors[name]
            # Update existing actor with MITRE data if missing description
            conn.execute(
                actors_table.update()
                .where(actors_table.c.name == name)
                .where(sa.or_(actors_table.c.description.is_(None), actors_table.c.description == ""))
                .values(
                    description=group["description"],
                    mitre_id=group["mitre_id"],
                    aliases=group["aliases"] or [],
                )
            )
        else:
            new_id = uuid.uuid4()
            actor_name_to_id[name] = new_id
            conn.execute(
                actors_table.insert().values(
                    id=str(new_id),
                    name=name,
                    aliases=group["aliases"] or [],
                    description=group["description"],
                    mitre_id=group["mitre_id"],
                    article_count=0,
                    metadata_={"source": "mitre_attack"},
                )
            )

    # 5. Seed malware/tools from MITRE
    malware_table = sa.table(
        "malware_families",
        sa.column("id", sa.dialects.postgresql.UUID),
        sa.column("name", sa.String),
        sa.column("aliases", ARRAY(sa.Text)),
        sa.column("description", sa.Text),
        sa.column("malware_type", sa.String),
        sa.column("article_count", sa.Integer),
        sa.column("metadata_", JSONB),
    )
    existing_malware = {
        row[0]: row[1] for row in conn.execute(sa.select(malware_table.c.name, malware_table.c.id)).fetchall()
    }
    malware_name_to_id = {}
    for mw in data["malware"]:
        name = mw["name"]
        if name in existing_malware:
            malware_name_to_id[name] = existing_malware[name]
            conn.execute(
                malware_table.update()
                .where(malware_table.c.name == name)
                .where(sa.or_(malware_table.c.description.is_(None), malware_table.c.description == ""))
                .values(
                    description=mw["description"],
                    malware_type=mw["malware_type"],
                    aliases=mw["aliases"] or [],
                )
            )
        else:
            new_id = uuid.uuid4()
            malware_name_to_id[name] = new_id
            conn.execute(
                malware_table.insert().values(
                    id=str(new_id),
                    name=name,
                    aliases=mw["aliases"] or [],
                    description=mw["description"],
                    malware_type=mw["malware_type"],
                    article_count=0,
                    metadata_={"source": "mitre_attack"},
                )
            )

    # 6. Build TTP technique_id -> UUID lookup
    ttp_id_result = conn.execute(
        sa.select(
            sa.column("technique_id", sa.String),
            sa.column("id", sa.dialects.postgresql.UUID),
        ).select_from(sa.table("ttps", sa.column("technique_id"), sa.column("id")))
    ).fetchall()
    ttp_tid_to_uuid = {row[0]: row[1] for row in ttp_id_result}

    # 7. Seed entity relationships (technique <-> actor/malware)
    rels_table = sa.table(
        "entity_relationships",
        sa.column("id", sa.dialects.postgresql.UUID),
        sa.column("source_type", sa.String),
        sa.column("source_id", sa.dialects.postgresql.UUID),
        sa.column("target_type", sa.String),
        sa.column("target_id", sa.dialects.postgresql.UUID),
        sa.column("relationship_type", sa.String),
        sa.column("confidence", sa.String),
        sa.column("source", sa.String),
        sa.column("created_by", sa.dialects.postgresql.UUID),
    )

    # Deduplicate relationships
    seen_rels = set()
    batch = []
    for rel in data["relationships"]:
        technique_uuid = ttp_tid_to_uuid.get(rel["technique_id"])
        if not technique_uuid:
            continue

        if rel["src_type"] == "threat_actor":
            other_uuid = actor_name_to_id.get(rel["src_name"])
            other_type = "threat_actor"
        else:
            other_uuid = malware_name_to_id.get(rel["src_name"])
            other_type = "malware"

        if not other_uuid:
            continue

        rel_key = (other_type, str(other_uuid), "ttp", str(technique_uuid), "uses")
        if rel_key in seen_rels:
            continue
        seen_rels.add(rel_key)

        batch.append(
            {
                "id": str(uuid.uuid4()),
                "source_type": other_type,
                "source_id": str(other_uuid),
                "target_type": "ttp",
                "target_id": str(technique_uuid),
                "relationship_type": "uses",
                "confidence": "confirmed",
                "source": "mitre_attack",
                "created_by": None,
            }
        )

    # Bulk insert in chunks
    for i in range(0, len(batch), 500):
        conn.execute(rels_table.insert(), batch[i : i + 500])


def downgrade() -> None:
    conn = op.get_bind()

    # Remove MITRE-seeded relationships
    conn.execute(sa.text("DELETE FROM entity_relationships WHERE source = 'mitre_attack'"))

    # Remove MITRE-seeded malware (article_count=0 and source=mitre)
    conn.execute(
        sa.text("DELETE FROM malware_families WHERE article_count = 0 AND metadata_->>'source' = 'mitre_attack'")
    )

    # Remove MITRE-seeded threat actors
    conn.execute(sa.text("DELETE FROM threat_actors WHERE article_count = 0 AND metadata_->>'source' = 'mitre_attack'"))

    # Make created_by non-nullable again
    op.alter_column("entity_relationships", "created_by", existing_type=sa.dialects.postgresql.UUID(), nullable=False)

    # Drop added columns
    op.drop_column("ttps", "is_subtechnique")
    op.drop_column("ttps", "detection")
    op.drop_column("ttps", "mitre_url")
    op.drop_column("ttps", "data_sources")
    op.drop_column("ttps", "platforms")
